import{_ as n,c as s,b as t,o as e}from"./app-90veb4I1.js";const l={};function p(r,a){return e(),s("div",null,a[0]||(a[0]=[t(`<h2 id="statistics" tabindex="-1"><a class="header-anchor" href="#statistics"><span>Statistics</span></a></h2><p>These functions help calculate statistical measures from arrays:</p><h3 id="_1-mad-sum-array" tabindex="-1"><a class="header-anchor" href="#_1-mad-sum-array"><span>1. <code>mad.sum(array)</code></span></a></h3><p>Returns the sum of all elements:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">array</td><td style="text-align:center;">Array</td><td style="text-align:center;">Input array</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">number</td><td style="text-align:center;">Total sum of elements</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> sum <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">sum</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: 6</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-mad-mean-array" tabindex="-1"><a class="header-anchor" href="#_2-mad-mean-array"><span>2. <code>mad.mean(array)</code></span></a></h3><p>Calculates the mean (average) of elements:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">array</td><td style="text-align:center;">Array</td><td style="text-align:center;">Input array</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">number</td><td style="text-align:center;">Average of elements</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> mean <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">mean</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: 2</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-mad-std-array" tabindex="-1"><a class="header-anchor" href="#_3-mad-std-array"><span>3. <code>mad.std(array)</code></span></a></h3><p>Computes the standard deviation of the array:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">array</td><td style="text-align:center;">Array</td><td style="text-align:center;">Input array</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">number</td><td style="text-align:center;">Standard deviation</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> std <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">std</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: ~0.82 (sample-dependent)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-mad-median-array" tabindex="-1"><a class="header-anchor" href="#_4-mad-median-array"><span>4. <code>mad.median(array)</code></span></a></h3><p>Finds the median value:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">array</td><td style="text-align:center;">Array</td><td style="text-align:center;">Input array</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">number</td><td style="text-align:center;">Middle value</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> median <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">median</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: 2</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="transformations" tabindex="-1"><a class="header-anchor" href="#transformations"><span>Transformations</span></a></h2><p>These functions are used to reshape or reformat arrays:</p><h3 id="_1-mad-reshape-array-newshape" tabindex="-1"><a class="header-anchor" href="#_1-mad-reshape-array-newshape"><span>1. <code>mad.reshape(array, newShape)</code></span></a></h3><p>Reshapes an array to the specified shape:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">array</td><td style="text-align:center;">Array</td><td style="text-align:center;">The original array</td></tr><tr><td style="text-align:center;">newShape</td><td style="text-align:center;">Array</td><td style="text-align:center;">New shape, e.g., [2, 2]</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Reshaped array</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> reshape <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">reshape</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [[1, 2], [3, 4]]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-mad-flatten-array" tabindex="-1"><a class="header-anchor" href="#_2-mad-flatten-array"><span>2. <code>mad.flatten(array)</code></span></a></h3><p>Flattens a nested array into a 1D array:</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">array</td><td style="text-align:center;">Array</td><td style="text-align:center;">A nested array</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Flattened 1D array</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Reshaped array</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> flatten <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">flatten</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [1, 2, 3, 4]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-mad-transpose-array" tabindex="-1"><a class="header-anchor" href="#_3-mad-transpose-array"><span>3. <code>mad.transpose(array)</code></span></a></h3><p>Transposes a 2D array (rows become columns):</p><table><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Type</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">array</td><td style="text-align:center;">2D Array</td><td style="text-align:center;">The matrix to flip</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Transposed matrix</td></tr><tr><td style="text-align:center;">Returns</td><td style="text-align:center;">Array</td><td style="text-align:center;">Reshaped array</td></tr></tbody></table><p><strong>Example</strong>:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> transpose <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">transpose</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// Result: [[1, 3], [2, 4]]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,39)]))}const c=n(l,[["render",p]]),o=JSON.parse('{"path":"/om-functions/statistics.html","title":"Statistics","lang":"en-US","frontmatter":{"lang":"en-US","title":"Statistics","description":"This page will guide you on how to install openmadness"},"headers":[{"level":2,"title":"Statistics","slug":"statistics","link":"#statistics","children":[{"level":3,"title":"1. mad.sum(array)","slug":"_1-mad-sum-array","link":"#_1-mad-sum-array","children":[]},{"level":3,"title":"2. mad.mean(array)","slug":"_2-mad-mean-array","link":"#_2-mad-mean-array","children":[]},{"level":3,"title":"3. mad.std(array)","slug":"_3-mad-std-array","link":"#_3-mad-std-array","children":[]},{"level":3,"title":"4. mad.median(array)","slug":"_4-mad-median-array","link":"#_4-mad-median-array","children":[]}]},{"level":2,"title":"Transformations","slug":"transformations","link":"#transformations","children":[{"level":3,"title":"1. mad.reshape(array, newShape)","slug":"_1-mad-reshape-array-newshape","link":"#_1-mad-reshape-array-newshape","children":[]},{"level":3,"title":"2. mad.flatten(array)","slug":"_2-mad-flatten-array","link":"#_2-mad-flatten-array","children":[]},{"level":3,"title":"3. mad.transpose(array)","slug":"_3-mad-transpose-array","link":"#_3-mad-transpose-array","children":[]}]}],"git":{"updatedTime":1751456764000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":1,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"om-functions/statistics.md"}');export{c as comp,o as data};
